// ListByDatasource returns all alert rules that reference the given datasource UID.
// It searches the JSON 'data' column for the datasourceUid field pattern.
// Used by Mimir and Loki rulers for federated alert rule management.
func (st DBstore) ListByDatasource(ctx context.Context, dsUID string) ([]ngmodels.AlertRule, error) {
	rules, err := st.ListAlertRules(ctx, &ngmodels.ListAlertRulesQuery{
		DataSourceUIDs: []string{dsUID},
	})
	if err != nil {
		return nil, err
	}
	result := make([]ngmodels.AlertRule, 0, len(rules))
	for _, r := range rules {
		result = append(result, *r)
	}
	return result, nil
}

func (f *RuleStore) ListByDatasource(_ context.Context, dsUID string) ([]models.AlertRule, error) {
	f.mtx.Lock()
	defer f.mtx.Unlock()
	f.RecordedOps = append(f.RecordedOps, GenericRecordedQuery{Name: "ListByDatasource", Params: []any{dsUID}})
	if err := f.Hook(GenericRecordedQuery{Name: "ListByDatasource", Params: []any{dsUID}}); err != nil {
		return nil, err
	}
	var result []models.AlertRule
	for _, rules := range f.Rules {
		for _, rule := range rules {
			for _, q := range rule.Data {
				if q.DatasourceUID == dsUID {
					result = append(result, *models.CopyRule(rule))
					break
				}
			}
		}
	}
	return result, nil
}
